         b=ix[mm]
         H[b,a] += -J*np.exp(1j*ph)
         H[a,b] += -J*np.exp(-1j*ph)
      en,vec=eigh(H)
      cache[key]=(states,ix,en,vec)
    states,ix,en,vec=cache[key]
    # Need J in cache! oops H depends J
    return 0

def preds(J):
  out=[]
  for e in records:
